class NodeStateVerifier:
    def __init__(self, mrbts_id: str, node_alias: str, ssh_vm_connection, admin_connection: NodeAdmin,
                 ssh_manager: NodeSSHManager,
                 watchdog, critical_alarms, allowed_alarms, test_specific_alarms, watchdog_config: dict,
                 logs_dir: str, mplane: str, scf_file: str, check_mplane: bool, detailed_console_log: bool,
                 x2_linked_btses: list, check_amf: bool):
        self.amf_mrbts = ""
        self.detailed_console_log = detailed_console_log
        self.rmods_with_faults = dict()
        self.mrbts_id = mrbts_id.replace("MRBTS-", "")
        self.node_alias = node_alias
        self.ssh_vm_connection = ssh_vm_connection
        self.admin_connection = admin_connection
        self.ssh_manager = ssh_manager
        self.watchdog = watchdog
        self.watchdog_config = watchdog_config
        self.logs_dir = logs_dir
        self.mplane = mplane
        self.check_mplane = self._log_info_check_mplane(check_mplane)
        self.check_amf = check_amf
        self.critical_alarms = critical_alarms
        self.temporary_allowed_alarms = []
        self.allowed_alarms = allowed_alarms
        self.test_specific_alarms = test_specific_alarms
        self.locked_objects = []
        self.blocked_objects = []
        self.dependent_radios = []
        self.affected_objects = []
        self.x2_linked_btses = x2_linked_btses
        self.scf = scf()
        self.scf_file = scf_file
        self.node_info = self.get_current_bts_info()
        self.cells_verifier = CellStateVerifier(self.admin_connection, self.node_alias, self.scf_file, self.node_info)
        self.cells_verifier.setup_cells()
        self.rmod_verifier = Rmod(self.admin_connection, self.node_alias, self.node_info, self.cells_verifier,
                                  self.scf_file)
        self.rmod_verifier.setup_modules()
        self.bbmod_verifier = Bbmod(self.admin_connection, self.node_alias, self.node_info, self.cells_verifier,
                                    self.rmod_verifier, self.scf_file)
        self.smod_verifier = Smod(self.admin_connection, self.node_alias, self.node_info, self.cells_verifier,
                                  self.rmod_verifier, self.scf_file)
        self.setup_modules()
        self.bts_fault_message = ""
        self.ims_alarm_verifier = IMS2AlarmVerifier()
        self.check_gps = self.check_if_gps_in_use()
        self.critical_alarm_detected = False
        self.module_not_detected = False

    @method_decorator("node_alias")
    def get_current_bts_info(self) -> dict:
        return self.admin_connection.get_bts_info(detailed_output=False, timeout=1800)

    def setup_modules(self):
        self.rmod_verifier.setup_modules()
        self.bbmod_verifier.setup_modules()
        self.smod_verifier.setup_modules()

    @method_decorator("node_alias")
    def get_software_from_partition(self, partition: Literal["Active", "Passive", "Planned"]) -> str:
        try:
            sw_info = self.admin_connection.get_software_info(timeout=300)
            sw_version = sw_info[f"{partition.capitalize()} SW version"]
            if "9" in sw_version.split("_", 3)[2] and sw_version.split("_", 3)[2] != "9900":
                sw_version = "_".join(["SBTS00", sw_version.split("_", 1)[1]])
            return sw_version
        except (AdminApiProcedureFailureException, SbtsOamAdminFailureException, AdminApiException) as e:
            self.admin_connection.teardown()
            self.admin_connection.setup_node_admin()
        except AdminApiConnectionClosedException as e:
            self.admin_connection.setup_node_admin()

    @method_decorator("node_alias")
    def verify_active_sw_version(self, sw: str, timeout: int = 600):
        def verify_mplane():
            if not self.is_mplane_accessible():
                raise
        if self.is_mplane_accessible():
            active_sw = self.get_software_from_partition("Active")
            if sw == active_sw:
                return True
            raise WrongSwVersion(f"Current active sw is {active_sw}, expected sw {sw}")
        wait_until_success(timeout, 10, verify_mplane)
        active_sw = self.get_software_from_partition("Active")
        if sw == active_sw:
            return True
        raise WrongSwVersion(f"Current active sw is {active_sw}, expected sw {sw}")

    def is_mplane_accessible(self):
        if self.check_mplane:
            return self.verify_mplane_access()
        return True

    def verify_mplane_access(self):
        url = f"https://{self.mplane if ':' not in self.mplane else f'[{self.mplane}]'}//"
        try:
            if not self.ssh_vm_connection.is_connected:
                self.ssh_vm_connection.connect()
            mplane_response = self.ssh_vm_connection.execute(f"curl -k -m 60 -I -s -X GET {url} | grep HTTP").rstrip()
            test_logger(f"Mplane response: {mplane_response}", "DEBUG")
            if "200" in mplane_response:
                return True
            return False
        except Exception as e:
            test_logger(e, "DEBUG")
            return False

    def verify_node_bts_state(self, hw_timer: int = None, return_error: bool = False, check_cells: bool = True):
        if not hw_timer:
            hw_timer = hw_timer
        return wait_until_success(hw_timer, 30, self.verify_bts_state, return_error, check_cells)

    def set_current_bts_info(self):
        """
        The set_current_bts_info function returns a dictionary of information about the BTS.
        :param self: Access the attributes and methods of the class
        :return: A dictionary of information about the bts

        """
        self.node_info = self.get_current_bts_info()
        self.rmod_verifier.node_info = self.node_info
        self.bbmod_verifier.node_info = self.node_info
        self.smod_verifier.node_info = self.node_info
        self.cells_verifier.node_info = self.node_info
        return

    @method_decorator("node_alias")
    def verify_smods_state(self):
        self.set_current_bts_info()
        self.smod_verifier.verify_all_modules_detected()
        entities_status = self.smod_verifier.verify_all_modules_state()
        faulty_entities = [entity for entity in entities_status for states in entity.values()
                           if any("Error" in state_value for state_value in states.values())]
        if faulty_entities:
            return False
        return True

    @method_decorator("node_alias")
    def verify_bts_state(self, return_error: bool = False, check_cells: bool = True):
        self.set_current_bts_info()
        self.verify_all_modules_detected()
        error = self.verify_all_state(return_error, check_cells)
        if error:
            test_logger(f"Checking state of {self.node_alias} failed with error {error}", "ERROR")
            return error

    def verify_all_state(self, return_error: bool = False, check_cells: bool = True):
        entities_status = []
        entities_status += self.rmod_verifier.verify_all_modules_state()
        entities_status += self.smod_verifier.verify_all_modules_state()
        entities_status += self.bbmod_verifier.verify_all_modules_state()
        temp_faulty_entities = [entity for entity in entities_status for states in entity.values()
                                if any("Error" in state_value for state_value in states.values())]
        self.module_not_detected = True if temp_faulty_entities else False
        if check_cells:
            entities_status += self.cells_verifier.verify_all_cells_state()
        faulty_entities = [entity for entity in entities_status for states in entity.values()
                           if any("Error" in state_value for state_value in states.values())]
        if faulty_entities:
            msg = "\n".join([f"{entity_id} : {result}" for entity in faulty_entities
                             for entity_id, result in entity.items()])
            if return_error:
                return msg
            raise VerificationBtsFailed(msg)

    @method_decorator("node_alias")
    def verify_all_modules_detected(self):
        radiomodules = self.rmod_verifier.verify_all_modules_detected()
        systemmodules = self.smod_verifier.verify_all_modules_detected()
        basebandmodules = self.bbmod_verifier.verify_all_modules_detected()
        if False in (radiomodules, systemmodules, basebandmodules):
            self.module_not_detected = True
            raise AssertionError("Not all modules are detected")
        self.module_not_detected = False

    @method_decorator("node_alias")
    def verify_no_unexpected_alarms(self) -> bool:
        test_logger(f"Checking unexpected alarms on {self.node_alias}")
        try:
            self.check_watchdog_alarms()
            self.verify_history_ims_alarms()
            self.disallow_watchdog_alarms(self.allowed_alarms + self.test_specific_alarms)
            time.sleep(10)
            self.verify_current_ims_alarms()
            self.check_watchdog_alarms()
            self.gps_check()
            if self.check_amf:
                self.verify_amf_status()
        except DisallowedIMSAlarmsDetected as ims_alarm_exception:
            self._set_rmods_with_faults(ims_alarm_exception.alarms)
            test_logger(f"{ims_alarm_exception}", console=False)
            faults = set(re.findall(r"fault_id:\s(\d[0-9]{1,6})", str(ims_alarm_exception)))
            output = str(ims_alarm_exception) if self.detailed_console_log else faults
            test_logger(f"Detected {'alarms' if self.detailed_console_log else 'faults'} "
                        f"in IMS on {self.node_alias}: {output}", "ERROR")
            raise
        except DisallowedAlarmsDetected as alarm_exception:
            self._set_rmods_with_faults(str(alarm_exception))
            self.bts_fault_message += f"\n{str(alarm_exception)}"
            faults = set(re.findall(r"fault_id:\s(\d[0-9]{1,6})", str(alarm_exception)))
            if any([fault for fault in faults if fault in self.critical_alarms]):
                self.critical_alarm_detected = True
            output = str(alarm_exception) if self.detailed_console_log else faults
            test_logger(f"Detected faults on {self.node_alias}: {output}", "error")
            test_logger(f"{alarm_exception}", console=False)
            raise
        finally:
            self.stop_watchdog_alarms()

    def gps_check(self):
        if self.check_gps:
            self.verify_gps()

    @method_decorator("node_alias")
    def verify_gps(self):
        try:
            if self.watchdog.is_alarm_active(fault_id="4420"):
                test_logger(f"GPS Firmware Ongoing - Waiting up to 25 min for it to finish", log_level="INFO")
                self.watchdog.wait_for_inactive_alarm(fault_id="4420", timeout=1500)
            return wait_until_success(1500, 10, self.verify_gps_state)
        except AssertionError as e:
            test_logger(f"Verify GPS failed: {e}", "error")

    @method_decorator("node_alias")
    def verify_gps_state(self):
        gps_info = self.admin_connection.get_gps_status()
        gps_types = ["gnsse", "gnssi"]
        if not any(gps_info.get(gps_type) for gps_type in gps_types):
            return False
        for gps_type in gps_types:
            if gps_info.get(gps_type):
                for gps in gps_info.get(gps_type):
                    if gps['stateInfo']['operationalState'] != "enabled" or \
                            gps['stateInfo'].get('availabilityStatus') in ["off line", "degraded"]:
                        raise AssertionError(f"GPS status failed, "
                                             f"operationalState: {gps['stateInfo']['operationalState']}")
        return True

    @method_decorator("node_alias")
    def verify_history_ims_alarms(self):
        ims_path = f"{self.logs_dir}/VERIFY_IMS_ALARMS_{self.node_alias}.ims2"
        self.admin_connection.collect_infomodel_log_from_current_session(ims_path)
        self.verify_unexpected_ims_alarms(self.allowed_alarms + self.test_specific_alarms +
                                          self.temporary_allowed_alarms,
                                          self.get_all_alarms_from_ims(ims_path))

    @method_decorator("node_alias")
    def verify_current_ims_alarms(self):
        self.verify_unexpected_ims_alarms(self.allowed_alarms + self.test_specific_alarms,
                                          self.get_current_alarms())

    @method_decorator("node_alias")
    def check_watchdog_alarms(self):
        self.watchdog.check_detected_alarms()

    @method_decorator("node_alias")
    def stop_watchdog_alarms(self):
        self.watchdog.stop_watching_alarms()

    @method_decorator("node_alias")
    def disallow_watchdog_alarms(self, alarms):
        self.watchdog.disallow_all_alarms_except_of(alarms)

    @method_decorator("node_alias")
    def _set_rmods_with_faults(self, alarm_report: Union[str, list]):
        if isinstance(alarm_report, list):
            unit_paths_with_faults = {alarm.unit_path for alarm in alarm_report}
        else:
            alarms_detected = [alarm for alarm in alarm_report.split("\n") if alarm]
            unit_paths_with_faults = {alarm.split("unit_path: ")[1].split(",")[0].split(" ")[-1]
                                      for alarm in alarms_detected}
        self.rmods_with_faults = {rmod: details for rmod, details in self.rmod_verifier.modules.items()
                                  if rmod in unit_paths_with_faults}
        if self.rmods_with_faults:
            test_logger(f"Detected rmods with faults: {self.rmods_with_faults}", console=False)

    @method_decorator("node_alias")
    def verify_node_state(self, hw_timer: int = None, alarm_timer: int = None, return_error: bool = False) -> bool:
        try:
            test_logger(f"Checking if {self.node_alias} is onair for {hw_timer} seconds")
            self.verify_node_bts_state(hw_timer, return_error)
            test_logger(f"Waiting for {alarm_timer} seconds if unexpected alarms will appear on {self.node_alias}")
            time.sleep(alarm_timer)
            test_logger(f"Checking alarms on {self.node_alias}")
            self.verify_no_unexpected_alarms()
        except FunctionTimeoutException as check_exception:
            self.bts_fault_message += f"\n{str(check_exception.exception)}"
            test_logger(check_exception, log_level="ERROR")
            self.verify_no_unexpected_alarms()
            raise
        return True

    def check_webem_connection(self, mode="LMP"):
        try:
            if mode == "LMP":
                self.admin_connection.get_active_alarms(timeout=300)
            else:
                mplane_admin = admin()
                mplane_connection = mplane_admin.setup_admin(alias=f"{self.node_alias}_mplane", bts_host=self.mplane)
                mplane_admin.get_active_alarms(connection=mplane_connection, timeout=300)
                mplane_admin.teardown_admin(connection=mplane_connection)
            return True
        except Exception as e:
            self.bts_fault_message += f"\n{str(e)}"
            test_logger(e, log_level="error")
            test_logger(traceback.format_exc(), log_level="debug", console=False)

            return False

    @method_decorator("node_alias")
    def get_rmods_serial_with_alarms(self) -> set:
        rmods_with_alarms = {rmod["Serial Number"] for alarm in self.admin_connection.get_active_alarms(timeout=300)
                             for rmod in self.rmod_verifier.modules.values() if rmod["Internal Id"]
                             in alarm["alarmingObjectIds"][0]["internal"]}
        return rmods_with_alarms

    @method_decorator("node_alias")
    def set_locked_object(self) -> None:
        for locked_object in self.locked_objects:
            if "RMOD" in locked_object:
                self.rmod_verifier.locked_modules.append(locked_object)
                locked_rmod_mapped_cells = self.rmod_verifier.modules.get(locked_object).get("Mapped Cells")
                for rmod, rmod_details in self.rmod_verifier.modules.items():
                    if rmod != locked_object:
                        other_rmod_mapped_cells = rmod_details.get("Mapped Cells")
                        self.cells_verifier.degraded_cells.update([cell for cell in locked_rmod_mapped_cells
                                                                   if cell in other_rmod_mapped_cells])
                self.cells_verifier.affected_cells = [mapped_cell for mapped_cell in locked_rmod_mapped_cells
                                                      if mapped_cell not in self.cells_verifier.degraded_cells]
                for mapped_cell in locked_rmod_mapped_cells:
                    for rat, cells_per_rat in self.cells_verifier.cells_per_rat.items():
                        if cells_per_rat.get(mapped_cell) and "Linked IoT Cell" in cells_per_rat[mapped_cell]:
                            linked_iot_cell = cells_per_rat[mapped_cell].get("Linked IoT Cell")
                            if linked_iot_cell not in self.cells_verifier.affected_cells:
                                self.cells_verifier.affected_cells.append(linked_iot_cell)
            if "BBMOD" in locked_object:
                self.bbmod_verifier.locked_modules.append(locked_object)
                bbmod_mapped_cells = self.bbmod_verifier.modules.get(locked_object).get("Mapped Cells")
                bbmod_mapped_cells_copy = bbmod_mapped_cells.copy()
                for mapped_cell in bbmod_mapped_cells_copy:
                    for bbmod, bbmod_details in self.bbmod_verifier.modules.items():
                        if mapped_cell in bbmod_details["Mapped Cells"] and bbmod != locked_object:
                            if mapped_cell in bbmod_mapped_cells:
                                bbmod_mapped_cells.remove(mapped_cell)
                if len(self.smod_verifier.modules) == 2:
                    bbmod_cabinet = locked_object.rsplit("/", 1)[0]
                    for smod, smod_details in self.smod_verifier.modules.items():
                        if bbmod_cabinet not in smod:
                            bbmod_mapped_cells -= set(smod_details["Mapped Cells"])
                self.cells_verifier.affected_cells = [mapped_cell for mapped_cell in bbmod_mapped_cells]
            if "CEL" in locked_object:
                self.cells_verifier.locked_cell.append(locked_object)
                for rat, cells_per_rat in self.cells_verifier.cells_per_rat.items():
                    if cells_per_rat.get(locked_object) and "Linked IoT Cell" in cells_per_rat[locked_object]:
                        linked_iot_cell = cells_per_rat[locked_object].get("Linked IoT Cell")
                        if linked_iot_cell:
                            self.cells_verifier.locked_cell.append(linked_iot_cell)

        test_logger(f"Locked objects: {self.locked_objects}", "DEBUG")
        test_logger(f"Affected cells: {self.cells_verifier.affected_cells}", "DEBUG")
        test_logger(f"Degraded cells: {self.cells_verifier.degraded_cells}", "DEBUG")
        test_logger(f"Locked cells: {self.cells_verifier.locked_cell}", "DEBUG")

    @method_decorator("node_alias")
    def set_blocked_object(self) -> None:
        for blocked_object in self.blocked_objects:
            if "site" in blocked_object:
                smod_mapped_cells = {cell for smod in self.smod_verifier.modules.keys()
                                     for cell in self.smod_verifier.modules.get(smod).get("Mapped Cells")}
                self.cells_verifier.blocked_cell = [mapped_cell for mapped_cell in smod_mapped_cells]
            if "CEL" in blocked_object:
                self.cells_verifier.blocked_cell.append(blocked_object)
        test_logger(f"Blocked objects: {self.cells_verifier.blocked_cell}", "DEBUG")

    @method_decorator("node_alias")
    def clear_locked_objects_list(self):
        self.locked_objects.clear()
        self.rmod_verifier.locked_modules.clear()
        self.rmod_verifier.affected_modules.clear()
        self.bbmod_verifier.locked_modules.clear()
        self.cells_verifier.affected_cells.clear()
        self.cells_verifier.locked_cell.clear()

    def clear_blocked_objects_list(self):
        self.blocked_objects.clear()
        self.rmod_verifier.affected_modules.clear()
        self.bbmod_verifier.affected_modules.clear()
        self.cells_verifier.affected_cells.clear()
        self.cells_verifier.blocked_cell.clear()

    @method_decorator("node_alias")
    def start_timestamp_cni_127210(self, timestamp=None):
        self.ims_alarm_verifier.set_start_timestamp(timestamp)

    @method_decorator("node_alias")
    def end_timestamp_cni_127210(self, timestamp=None):
        self.ims_alarm_verifier.set_end_timestamp(timestamp)

    @method_decorator("node_alias")
    def get_all_alarms_from_ims(self, ims_path: str) -> list:
        self.end_timestamp_cni_127210()
        return [alarm['object'] for alarm in self.ims_alarm_verifier.get_alarms_set_in_passed_timeframe(ims_path)]

    def verify_unexpected_ims_alarms(self, allowed_alarms: list, detected_alarms: list):
        def fix_alarms_dict(alarms_detected: dict, alarms_allowed: dict):
            for attribute, value in alarms_allowed.items():
                if not value:
                    alarms_detected[attribute] = None

        allowed_alarms_log = [f"{alarm}" for alarm in allowed_alarms]
        detected_alarms_log = [f"{alarm}" for alarm in detected_alarms]
        new_line = '\n'
        test_logger(f"ALLOWED ALARMS: \n{new_line.join(allowed_alarms_log)}", "DEBUG")
        test_logger(f"DETECTED ALARMS: \n{new_line.join(detected_alarms_log)}", "DEBUG")
        disallowed_alarms = []
        for detected_alarm in detected_alarms:
            detected_alarm_copy = {alarm_attribute: attribute_value for alarm_attribute, attribute_value
                                   in vars(detected_alarm).items() if alarm_attribute != '_unit_path'}
            for allowed_alarm in allowed_alarms:
                tmp_detected = copy.deepcopy(detected_alarm_copy)
                tmp_allowed = {alarm_attribute: attribute_value for alarm_attribute, attribute_value
                               in vars(allowed_alarm).items() if alarm_attribute != '_unit_path'}
                fix_alarms_dict(tmp_detected, tmp_allowed)
                fix_alarms_dict(tmp_allowed, tmp_detected)
                if tmp_detected == tmp_allowed:
                    break
            else:
                disallowed_alarms.append(detected_alarm)
        if disallowed_alarms:
            alarms = "\n".join([f"Alarm: {vars(alarm)}" for alarm in disallowed_alarms])
            self.bts_fault_message += f"\n{alarms}"
            if any([alarm.fault_id for alarm in disallowed_alarms if alarm.fault_id in self.critical_alarms]):
                self.critical_alarm_detected = True
            faults_id = ', '.join({alarm.fault_id for alarm in disallowed_alarms if alarm.fault_id})
            output = alarms if self.detailed_console_log else faults_id
            test_logger(f"Detected {'alarms' if self.detailed_console_log else 'faults'} "
                        f"in IMS on {self.node_alias}: {output}", "ERROR")
            raise DisallowedIMSAlarmsDetected(detected_alarms=disallowed_alarms)
        test_logger("No disallowed alarms detected", console=False)

    def get_current_alarms(self):
        active_alarms = []
        for alarm in self.admin_connection.get_alarms():
            alarm_obj = Alarm(
                alarm_id=alarm.get('alarmId'),
                fault_id=alarm.get('faultId'),
                fault_name=alarm.get('alarmInformation')['faultDescription'],
                reason=alarm.get('reason'),
                severity=alarm.get('severity'),
                unit_path=alarm.get('alarmingObjectIds')[0].get('configuration', None))
            active_alarms.append(alarm_obj)
        return active_alarms

    def check_if_gps_in_use(self):
        try:
            return self.verify_gps_state()
        except Exception as e:
            test_logger(e, "DEBUG")
            test_logger("Verification gps will be skipped in test", "warn")
            return False

    @method_decorator("node_alias")
    def check_hwf_migration(self):
        hwf_info = self.get_hwf_infomodel_info()
        if hwf_info:
            hwf_errors = {infomodel_object: info for infomodel_object, info in hwf_info.items()
                          if info.get("availabilityStatus") != 'Online' or info.get("operationalState") != 'Enabled'}

            if hwf_errors:
                raise HWFMigrationError(f"HWF Migration failed. Objects with not expected states: {hwf_errors}")
            else:
                test_logger("HWF Migration completed successfully")
        else:
            raise HWFMigrationError(f"HWF Migration failed. Couldn't get HWF informations")

    @method_decorator("node_alias")
    def get_hwf_infomodel_info(self):
        def get_hwf(infomodel_object: str) -> dict:
            try:
                return self.admin_connection.get_parameters(infomodel_object, pattern=".*")
            except AdminApiProcedureFailureException as e:
                test_logger(str(e), "DEBUG")
                if 'Object not found' in str(e):
                    test_logger(f"HWF Migration feature is not enabled, check is skipped. "
                                f"Infomodel object doesn't exists: {infomodel_object}", "INFO", console=False)
                return {}

        internal_ids = [self.smod_verifier.modules[smod].get("Internal Id") for smod in self.smod_verifier.modules]
        hwf_status = defaultdict()
        for index, smod in list(zip(itertools.count(1, 3), internal_ids)):
            if len(self.smod_verifier.modules) == 1:
                bts_l_side_match = re.search(r"RUNTIME_VIEW-[1-4]", smod)
                btsl_side = bts_l_side_match.group(0).split("-")[-1] if bts_l_side_match else "1"
            else:
                btsl_side = index
            baseband_block_info = f"/MRBTS-1/RAT-1/BASEBAND_BLOCK-{btsl_side}/HWF-1"
            rem_info = f"/MRBTS-1/RAT-1/REM-{btsl_side}/HWF-1"
            for object_name in [baseband_block_info, rem_info]:
                hwf_info = get_hwf(object_name)
                if not hwf_info:
                    return
                availability_status = hwf_info.get("stateInfo").get("availabilityStatus")
                operational_state = hwf_info.get("stateInfo").get("operationalState")
                hwf_status[object_name] = {'availabilityStatus': availability_status,
                                           'operationalState': operational_state}
        hwf_status = {infomodel_object: info for infomodel_object, info in hwf_status.items()}
        test_logger(f"HWF Status: {hwf_status}", "INFO", console=False)
        return hwf_status

    def _log_info_check_mplane(self, check_mplane: bool):
        if not check_mplane:
            test_logger(f"check_mplane is set to False. Checking mplane will be disabled on {self.node_alias}", "WARN")
        return check_mplane

    @method_decorator("node_alias")
    def verify_amf_status(self):
        try:
            test_logger("Checking AMF status")
            wait_until_success(300, 30, self.verify_amf)
        except Exception as e:
            test_logger("Verification AMF failed", "ERROR")
            self.bts_fault_message += f"\n{str(e)}"
            raise e

    @method_decorator("node_alias")
    def verify_amf(self):
        amf_status = self.get_amf_info()
        amf_status_fail = False
        if amf_status:
            allowed_statuses = ["Active"]
            self.set_current_bts_info()
            self.cells_verifier.verify_all_cells_state()
            test_logger(f"Energy saving cells: {self.cells_verifier.energy_saving_cells}", "DEBUG")
            gnb_cu_type = self.cells_verifier.gnb_cu_type or ""
            if self.cells_verifier.energy_saving_cells and "NSA" in gnb_cu_type:
                allowed_statuses.append("Inactive")
            if any("NRCELL" in cell for cell in self.cells_verifier.locked_cell) and "Inactive" not in allowed_statuses:
                allowed_statuses.append("Inactive")
            for amf, amf_info in amf_status.items():
                if amf_info["administrativeState"] == "Unlocked" and amf_info["ngLinkStatus"] not in allowed_statuses:
                    amf_status_fail = True
        if amf_status_fail:
            raise WrongAMFStatus(f"Status of AMF with not expected state: {dict(amf_status)}")

    @method_decorator("node_alias")
    def get_amf_info(self) -> Union[defaultdict, None]:
        def get_scf_object():
            for np_nr in range(1, 10):
                try:
                    current_object = f"/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-{np_nr}/SCF-1/MRBTS_A-{self.mrbts_id}"
                    self.admin_connection.get_parameters(current_object, pattern=".*")
                    return current_object
                except AdminApiProcedureFailureException:
                    continue
            return None

        scf_object = get_scf_object()
        if scf_object:
            if self.x2_linked_btses:
                bts_to_check = self.x2_linked_btses if not self.amf_mrbts else [self.amf_mrbts]
            else:
                bts_to_check = [self.mrbts_id]
            amf_info = defaultdict(dict)
            internal_ids = [self.smod_verifier.modules[smod].get("Internal Id") for smod in self.smod_verifier.modules]
            bts_l_side_match = re.search(r"RUNTIME_VIEW-[1-4]", internal_ids[0])
            btsl_side = bts_l_side_match.group(0).split("-")[-1] if bts_l_side_match else "1"
            for mrbts_id in bts_to_check:
                for amf_nr in range(1, 10):
                    try:
                        amf_scf_object = f"{scf_object}/NRBTS_A-{mrbts_id}/SERVEDAMF_A-{amf_nr}"
                        amf_administrative_state = self.admin_connection.get_parameters(amf_scf_object,
                                                                                        pattern=".*")
                        administrative_state = amf_administrative_state.get("administrativeState", "")
                        amf_infomodel = f"/MRBTS-1/RAT-1/RUNTIME_VIEW-{btsl_side}/MRBTS_R-1/NRBTS_R-{mrbts_id}" \
                                        f"/SERVEDAMF_R-{amf_nr}"
                        amf_link_status = self.admin_connection.get_parameters(amf_infomodel, pattern=".*")
                        nglink_status = amf_link_status.get("ngLinkStatus", "")
                        amf_info[f"AMF-{amf_nr}"] = {"administrativeState": administrative_state,
                                                     "ngLinkStatus": nglink_status}
                    except AdminApiProcedureFailureException:
                        break
            return amf_info
        return None


class ModuleStateVerifier(ABC):
    def __init__(self, admin_connection=None, node_alias=None, node_info=None, cells_verifier=None, rmod_verifier=None,
                 scf_file=None, module_type=None):
        self.admin_connection = admin_connection
        self.node_alias = node_alias
        self.node_info = node_info
        self.cells_verifier = cells_verifier
        self.rmod_verifier = rmod_verifier
        self.module_type = module_type
        self.scf = scf()
        self.scf_file = scf_file
        self.locked_modules = []
        self.blocked_modules = []
        self.affected_modules = []
        self.modules = None

    @method_decorator("node_alias")
    def setup_modules(self):
        self.modules = self.get_modules()

    @abstractmethod
    def get_modules(self):
        pass

    def verify_all_modules_detected(self):
        return len(self.modules) == len(self.get_modules())

    @method_decorator("node_alias")
    def verify_all_modules_state(self):
        modules_states = self.get_all_modules_state()
        modules_states = {module: details for module, details in modules_states.items() if module}
        modules_with_status = []
        for module, module_state in modules_states.items():
            if module in self.locked_modules:
                expected_state = "locked"
            elif module in self.blocked_modules:
                expected_state = "blocked"
            elif module in self.affected_modules:
                expected_state = "dependency"
            else:
                expected_state = "onair"
            modules_with_status.append(self.verify_module_state(module, module_state, expected_state))
        return modules_with_status

    @method_decorator("node_alias")
    def get_module_status(self, module_distname: str):
        modules_states = self.get_all_modules_state()
        module_states = {module: details for module, details in modules_states.items()
                         if module and module == module_distname}
        module_state = module_states[module_distname]
        if module_distname in self.locked_modules:
            expected_state = "locked"
        elif module_distname in self.blocked_modules:
            expected_state = "blocked"
        elif module_distname in self.affected_modules:
            expected_state = "dependency"
        else:
            expected_state = "onair"
        return self.verify_module_state(module_distname, module_state, expected_state)

    @method_decorator("node_alias")
    def get_current_bts_info(self):
        return self.admin_connection.get_bts_info(detailed_output=False, timeout=1800)

    @staticmethod
    def _set_module_type(module_info):
        if not module_info.get("productName"):
            return None
        flexi_modules = ["FSMF", "FBBC", "FBBA", "FSIH", "FBIH"]
        for module in flexi_modules:
            if module in module_info.get("productName"):
                return module
        return module_info.get("productName").split()[0]

    @method_decorator("node_alias")
    def get_dict_of_module_id_and_serial_no(self, module_type):
        return {module.get("id").get("configuration"): {"Serial Number": module.get("serialNumber"),
                                                        "Mapped Cells":
                                                            self.cells_verifier.get_cells_mapped_to_module(module),
                                                        "Internal Id": module.get("id").get("internal"),
                                                        "Module Type": self._set_module_type(module)}
                for module in (self.node_info.get(module_type) if module_type != "radioModules"
                               else list(chain(*self.node_info.get("radioModules").values())))}

    @staticmethod
    def get_expected_status_for_module(expected_state="onair", is_rf_shared=False) -> dict:
        expected_states_values = {}
        if expected_state == "onair":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'operationalState': ["enabled"],
                                      'proceduralStatus': ["configured"]}
        elif expected_state == "locked":
            expected_states_values = {'administrativeState': ["Locked", "locked"],
                                      'operationalState': ["enabled"],
                                      'proceduralStatus': ["configured"]}

        elif expected_state == "dependency":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'availabilityStatus': ["dependency", "failed"],
                                      'blockingState': ["Unblocked", "unblocked"],
                                      'operationalState': ["disabled"],
                                      'proceduralStatus': ["configured"]}
            if is_rf_shared:
                expected_states_values["operationalState"] = ["enabled"]
                expected_states_values["availabilityStatus"] = ["degraded"]

        elif expected_state == "blocked":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'availabilityStatus': ["off line"],
                                      'blockingState': ["Blocked", "blocked"],
                                      'operationalState': ["disabled"],
                                      'proceduralStatus': ["configured"]}
        return expected_states_values

    def get_all_modules_state(self) -> dict:
        return {module.get("id").get("configuration"): {state: state_value for state, state_value in
                                                        module.get("status").items()}
                for module in (self.node_info.get(self.module_type) if self.module_type != "radioModules"
                               else list(chain(*self.node_info.get("radioModules").values())))}

    @verify_state_decorator("node_alias")
    def verify_module_state(self, module_id, module_states, expected_state="onair", is_rf_shared=False):
        expected_statuses = self.get_expected_status_for_module(expected_state, is_rf_shared)
        if expected_state == "locked" and self.modules[module_id].get("Protocol") == "O-RAN":
            expected_statuses["operationalState"] = ["disabled"]
        result = {
            module_id: {state: f"State as expected {state_value}" if state_value in expected_statuses.get(state) else
            f"Error current value {state_value} not in expected values list {expected_statuses.get(state)}"
                        for state, state_value in module_states.items() if state in expected_statuses.keys()}
        }
        return result

    def _set_cells_for_module(self, module: dict):
        for module_type, module_details in module.items():
            for mapped_cell in module_details["Mapped Cells"]:
                try:
                    cell_iot_mode = self.scf.get_value_from_scf(dist_name=mapped_cell, p_name="nbIoTMode")
                    if cell_iot_mode in self.cells_verifier.iot_modes:
                        mapped_cell_details = ""
                        for rat, cells in self.cells_verifier.cells_per_rat.items():
                            if mapped_cell in cells:
                                mapped_cell_details = cells[mapped_cell]
                        shared_cell = self.cells_verifier.get_linked_iot_cell(self.cells_verifier.cells_per_rat,
                                                                              mapped_cell, mapped_cell_details)
                        if shared_cell and shared_cell not in module_details["Mapped Cells"]:
                            module_details["Mapped Cells"].append(shared_cell)
                except KeyError:
                    pass

class Rmod(ModuleStateVerifier):

    def __init__(self, admin_connection, node_alias, node_info, cells_verifier, scf_file, module_type="radioModules"):
        super().__init__(admin_connection, node_alias, node_info, cells_verifier, None, scf_file, module_type)
        self.shared_radioModules = None

    def get_modules(self):
        return self.get_node_radio_modules_with_serial_numbers()

    def setup_modules(self):
        super().setup_modules()
        self.shared_radioModules = self.get_shared_radio_modules_with_serial_numbers()

    @method_decorator("node_alias")
    def get_node_radio_modules_with_serial_numbers(self):
        self.scf.load_scf(self.scf_file)
        rmods = self.get_dict_of_module_id_and_serial_no("radioModules")
        rmods = {rmod: details for rmod, details in rmods.items() if rmod}
        rmods_parameters = self.admin_connection.get_parameters_for_all("RMOD")
        for rmod, rmod_details in rmods.items():
            rmod_params = self.admin_connection.get_parameters(rmod_details["Internal Id"])
            try:
                rmod_details["Protocol"] = self.scf.get_value_from_scf(dist_name=rmod, p_name="protocol")
            except KeyError:
                pass
            try:
                rmod_details["Ip Address"] = self.get_rmod_ip_address_from_ims(rmods_parameters,
                                                                               rmod_details["Serial Number"])
            except:
                rmod_details["Ip Address"] = ""
            try:
                shared_ru_control = self.scf.get_value_from_scf(dist_name=rmod, p_name="actSharedRUIndControl")
            except KeyError:
                shared_ru_control = ""
            if rmod_params.get("radioMasterDN") and "SMOD_EXT" in rmod_params.get("radioMasterDN") \
                    and shared_ru_control.lower() != 'true':
                rmod_details["Eligible For Reset"] = False
            else:
                rmod_details["Eligible For Reset"] = True
        return rmods

    @method_decorator("node_alias")
    def get_shared_radio_modules_with_serial_numbers(self):
        return {rmod: rmod_details for rmod, rmod_details in self.modules.items()
                for cablink in self.node_info.get("cables")
                if "SMOD_EXT" in cablink.get("firstEndPointId").get("configuration", "")
                and rmod in cablink.get("secondEndPointId").get("configuration", "")}

    @method_decorator("node_alias")
    def get_rmod_ip_address_from_ims(self, rmods: list, serial_number: str) -> str:
        for rmod in rmods:
            if rmod["serialNumber"] == serial_number:
                return rmod.get("ipAddress", "")
        return ""


class Bbmod(ModuleStateVerifier):
    def __init__(self, admin_connection, node_alias, node_info, cells_verifier, rmod_verifier, scf_file,
                 module_type="basebandModules"):
        super().__init__(admin_connection, node_alias, node_info, cells_verifier, rmod_verifier, scf_file, module_type)

    def get_modules(self):
        return self.get_node_baseband_modules_with_serial_numbers()

    @method_decorator("node_alias")
    def get_node_baseband_modules_with_serial_numbers(self):
        bbmods = self.get_dict_of_module_id_and_serial_no("basebandModules")
        bbmods = {bbmod: details for bbmod, details in bbmods.items() if bbmod}
        for bbmod, bbmod_details in bbmods.items():
            bbmod_params = self.admin_connection.get_parameters(bbmod_details["Internal Id"])
            if bbmod_params.get("geranSupport") or bbmod_params.get("utranSupport"):
                bbmod_details["Eligible For Reset"] = False
            else:
                bbmod_details["Eligible For Reset"] = True
            bbmod_details["Radio Modules"] = self.get_rmods_per_bbmod(bbmod)
        self._set_cells_for_module(bbmods)
        return bbmods

    @method_decorator("node_alias")
    def get_rmods_per_bbmod(self, bbmod_distname):
        self.scf.load_scf(self.scf_file)
        return {self.scf.get_value_from_scf(dist_name=cablink, p_name="secondEndpointDN")
                for cablink in self.scf.get_all_dist_names_by_pattern(".*CABLINK-.*")
                if "RMOD" in self.scf.get_value_from_scf(dist_name=cablink, p_name="secondEndpointDN")
                and bbmod_distname in self.scf.get_value_from_scf(dist_name=cablink, p_name="firstEndpointDN")}


class Smod(ModuleStateVerifier):

    def __init__(self, admin_connection, node_alias, node_info, cells_verifier, rmod_verifier, scf_file,
                 module_type="systemModules"):
        super().__init__(admin_connection, node_alias, node_info, cells_verifier, rmod_verifier, scf_file, module_type)

    def get_modules(self):
        return self.get_node_system_modules_with_serial_numbers()

    @method_decorator("node_alias")
    def get_node_system_modules_with_serial_numbers(self):
        def get_rmod_from_serial_number(serial_number: str, mapped_smod: str) -> Union[str, None]:
            for rmod, rmod_details in self.rmod_verifier.modules.items():
                if rmod_details["Serial Number"] == serial_number:
                    self.rmod_verifier.modules[rmod]["Mapped SMOD"] = mapped_smod
                    return rmod
            return None

        smods = self.get_dict_of_module_id_and_serial_no("systemModules")
        smods = {smod: details for smod, details in smods.items() if smod}

        for smod, smod_details in smods.items():
            rmods_serial_number = set()
            try:
                bts_l_list = ["1", "4"] if len(smods) == 2 else ['1']
                for bts_l in bts_l_list:
                    smod_parameters = self.admin_connection.get_parameters(f"/MRBTS-1/RAT-1/BTS_L-{bts_l}"
                                                                           f"/EQM_L-1/CABINET_L-1/SMOD_L-1")
                    ims_serial = smod_parameters.get("serialNumber")
                    if smod_details["Serial Number"] == ims_serial:
                        for rmod_number in range(1, 100):
                            try:
                                rmod_parameter = self.admin_connection.get_parameters(
                                    f"/MRBTS-1/RAT-1/BTS_L-{bts_l}/EQM_L-1/RMOD_L-{rmod_number}")
                                rmods_serial_number.update({rmod_parameter.get("serialNumber")})
                            except:
                                break
                smod_role = "Primary" if smod.endswith("-1") else "Secondary"
                smod_details["Radio Modules"] = [get_rmod_from_serial_number(serial_number, smod_role)
                                                 for serial_number in rmods_serial_number]
            except Exception as e:
                test_logger(e, "DEBUG")
        self.scf.load_scf(self.scf_file)
        self._set_cells_for_module(smods)
        return smods


class CellStateVerifier:

    def __init__(self, admin_connection: NodeAdmin = None, node_alias: str = None, scf_file: str = None,
                 node_info: dict = None, cell_type: str = None):
        self.degraded_cells = set()
        self.dss_affected_cell = []
        self.locked_cell = []
        self.blocked_cell = []
        self.affected_cells = []
        self.energy_saving_cells = set()
        self.serial_console_cells = []
        self.admin_connection = admin_connection
        self.node_alias = node_alias
        self.scf = scf()
        self.scf_file = scf_file
        self.cell_type = cell_type
        self.node_info = node_info
        self.gnb_cu_type = None
        self.cells_per_rat = None
        self._rat = None
        self.duplex_variant = None
        self.dss_cells = None
        self.setup_energy_saving = False
        self.iot_modes = ["inband", "guardband", "guardband-NR"]

    @method_decorator("node_alias")
    def setup_cells(self):
        self.gnb_cu_type = self.get_gnb_cu_type()
        self.cells_per_rat = self.get_cells_per_rat()
        self._rat = self.get_bts_rat()
        self.duplex_variant = self.get_duplex_mode()

    @method_decorator("node_alias")
    def verify_all_cells_state(self):
        all_cells = self.get_all_cells_state()
        if not self.setup_energy_saving:
            self.energy_saving_cells.clear()
        cells_status = []
        for cell in all_cells.keys():
            if cell in self.locked_cell:
                expected_state = "locked"
            elif cell in self.blocked_cell:
                expected_state = "blocked"
            elif cell in self.affected_cells:
                expected_state = "dependency"
            elif cell in self.degraded_cells:
                expected_state = "degraded"
            elif cell in self.energy_saving_cells:
                expected_state = "energy_saving"
            else:
                expected_state = "onair"
            cells_status.append(self.verify_cell_state(cell, all_cells, expected_state))
        return cells_status

    @method_decorator("node_alias")
    def verify_rat_cells_state(self, rat: str):
        all_cells = self.get_rat_cells_state(rat)
        cells_status = []
        for cell in all_cells.keys():
            if cell in self.locked_cell:
                expected_state = "locked"
            elif cell in self.blocked_cell:
                expected_state = "blocked"
            elif cell in self.affected_cells:
                expected_state = "dependency"
            elif cell in self.degraded_cells:
                expected_state = "degraded"
            else:
                expected_state = "onair"
            cells_status.append(self.verify_cell_state(cell, all_cells, expected_state))
        return cells_status

    @method_decorator("node_alias")
    def get_gnb_cu_type(self):
        """
        The _get_nr_cell_deployment_type function returns the deployment type of the NR cell.
        The function returns None if no information is available.

        :param self: Access the class attributes
        :return: The deployment type of the cell

        """

        return self.node_info["gNbCuType"] if "gNbCuType" in self.node_info.keys() else None

    @method_decorator("node_alias")
    def get_bts_rat(self):
        return [rat for rat in self.node_info["cells"] if self.node_info["cells"][rat]]

    @method_decorator("node_alias")
    def get_cells_mapped_to_module(self, module_details):
        cells_internal = self.admin_connection.get_cell_mapping_by_module_id(module_details.get("id").get("internal"),
                                                                             timeout=300)
        cells_list = list(chain(*self.node_info.get("cells").values()))
        cells_configuration = [cell.get("id").get("configuration") for cell in cells_list
                               if cell.get("id").get("internal") in cells_internal]
        return cells_configuration

    @method_decorator("node_alias")
    def get_current_bts_info(self):
        return self.admin_connection.get_bts_info(detailed_output=False, timeout=1800)

    def get_expected_status_for_cell(self, cell_id: str, dict_of_cells: dict, expected_state: str = "onair"):
        def set_expected_status_for_iot_cell():
            for rat, cells_per_rat in self.cells_per_rat.items():
                if cells_per_rat.get(cell_id) and dict_of_cells[cell_id].get("IoT Cell"):
                    host_cell = cells_per_rat[cell_id].get("Linked Host Cell")
                    if host_cell:
                        host_cell_states = dict_of_cells.get(host_cell)
                        host_energy_saving = host_cell_states.get("EnergySaving", "")
                        if str(host_energy_saving).lower() == "energysaving":
                            expected_states_values['operationalState'] = ["disabled"]
                        elif str(host_energy_saving).lower() == "switchingoff":
                            expected_states_values['operationalState'] = ["enabled", "disabled"]

        cell_states = dict_of_cells.get(cell_id)
        expected_states_values = {}
        energy_saving = cell_states.get("EnergySaving", "")
        energy_saving_cell = str(energy_saving).lower() == "energysaving"
        switching_off_energysaving = str(energy_saving).lower() == "switchingoff"
        if switching_off_energysaving:
            operational_states = ["enabled", "disabled"]
        elif energy_saving_cell:
            operational_states = ["disabled"]
        else:
            operational_states = ["enabled"]
        if energy_saving_cell or switching_off_energysaving:
            self.energy_saving_cells.update({cell_id})
        if expected_state == "onair":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'operationalState': operational_states,
                                      'proceduralStatus': ["configured"]}
        elif expected_state == "energy_saving":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'operationalState': ["enabled", "disabled"],
                                      'proceduralStatus': ["configured"]}
        elif expected_state == "locked":
            expected_states_values = {'administrativeState': ["Locked", "locked"],
                                      'operationalState': ["disabled"],
                                      'availabilityStatus': ["off line"]}

        elif expected_state == "degraded":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'availabilityStatus': ["dependency", "degraded"],
                                      'blockingState': ["Unblocked", "unblocked"],
                                      'operationalState': ["disabled", "enabled"]}  # not initialized?
        elif expected_state == "dependency":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'availabilityStatus': ["dependency", 'failed'],
                                      'blockingState': ["Unblocked", "unblocked"],
                                      'operationalState': ["disabled"],
                                      'proceduralStatus': ["configured", "not initialized"]}  # not initialized?
            iot_mode = cell_states.get("IoT Mode", "disabled")
            if cell_states and iot_mode in self.iot_modes:
                cell_details = {key: value for rat, cellss_per_rat in self.cells_per_rat.items() if
                                cellss_per_rat.get(cell_id)
                                for key, value in cellss_per_rat.get(cell_id).items()}
                linked_iot_cell = cell_details.get("Linked IoT Cell") or cell_details.get("Linked Host Cell")
                if linked_iot_cell in self.affected_cells:
                    expected_states_values['availabilityStatus'] = ["dependency", "off line"]
                else:
                    expected_states_values['operationalState'] = ["enabled"]
                    expected_states_values['availabilityStatus'] = ["degraded"]
                if cell_states and cell_states.get("IoT Cell") and iot_mode.lower() != "inband":
                    expected_states_values['availabilityStatus'] = ["off line"]
        elif expected_state == "blocked":
            expected_states_values = {'administrativeState': ["Unlocked", "unlocked"],
                                      'availabilityStatus': ["off line"],
                                      'blockingState': ["Blocked", "blocked"],
                                      'operationalState': ["disabled"],
                                      'proceduralStatus': ["configured"]}
        if (cell_id in self.serial_console_cells or cell_id in self.dss_affected_cell
                and cell_id not in self.energy_saving_cells):
            expected_states_values['availabilityStatus'] = ["degraded"]
        if expected_state != "energy_saving":
            set_expected_status_for_iot_cell()
        return expected_states_values

    def set_current_bts_info(self):
        """
        The set_current_bts_info function returns a dictionary of information about the BTS.
        :param self: Access the attributes and methods of the class
        :return: A dictionary of information about the bts

        """
        self.node_info = self.get_current_bts_info()

    @method_decorator("node_alias")
    def get_all_cells_state(self):
        list_of_cells = list(chain(*self.node_info.get("cells").values()))
        cells_states = {cell.get("id").get("configuration"): {state: state_value for state, state_value in
                                                              cell.get("status").items()}
                        for cell in list_of_cells}

        for cell, cell_state in cells_states.items():
            for cell_inf in list_of_cells:
                if cell == cell_inf.get("id").get("configuration"):
                    cell_state["EnergySaving"] = cell_inf.get("energySavingState")
            for rat, cells in self.cells_per_rat.items():
                if cell in cells:
                    cell_state["IoT Cell"] = self.cells_per_rat[rat][cell].get("IoT Cell")
                    cell_state["IoT Mode"] = self.cells_per_rat[rat][cell].get("IoT Mode", "disabled")

        return cells_states

    @method_decorator("node_alias")
    def get_rat_cells_state(self, rat_to_get: str):
        rat = rat_to_get.lower()
        if rat not in ("lte", "nr", "wcdma", "gsm"):
            raise ValueError("Invalid state value. Excpected one of: lte, nr, wcdma, gsm")

        list_of_cells = list(self.node_info.get("cells").get(rat))
        cells_states = {cell.get("id").get("configuration"): {state: state_value for state, state_value in
                                                              cell.get("status").items()}
                        for cell in list_of_cells}

        for cell, cell_state in cells_states.items():
            for cell_inf in list_of_cells:
                if cell == cell_inf.get("id").get("configuration"):
                    cell_state["EnergySaving"] = cell_inf.get("energySavingState")
            for rat_cell in self.cells_per_rat[rat]:
                if cell == rat_cell:
                    cell_state["IoT Cell"] = self.cells_per_rat[rat][cell].get("IoT Cell")

        return cells_states

    @verify_state_decorator("node_alias")
    def verify_cell_state(self, cell_id, dict_of_cells, expected_state="onair"):
        expected_statuses = self.get_expected_status_for_cell(cell_id, dict_of_cells, expected_state)
        result = {
            cell_id: {state: f"State as expected {state_value}" if state_value in expected_statuses.get(state) else
            f"Error current value {state_value} not in expected values list {expected_statuses.get(state)}"
                      for state, state_value in dict_of_cells.get(cell_id).items() if state in expected_statuses.keys()}
        }
        if cell_id in self.energy_saving_cells and expected_state == "onair":
            energy_saving = dict_of_cells[cell_id].get("EnergySaving", "")
            energy_saving_cell = str(energy_saving).lower() in ["energysaving", "switchingoff"]
            result[cell_id]["EnergySaving"] = f"State as expected {energy_saving}" if energy_saving_cell \
                else f"Error current value {energy_saving} not in expected value"
        return result

    @method_decorator("node_alias")
    def get_cells_per_rat(self):
        band_keys = {"nr": "band",
                     "lte": "bandNumber",
                     "gsm": "gsmBand"}
        cells = {rat: {cell.get("id").get("configuration"): {"band": cell.get(band_keys.get(rat)),
                                                             "technology": cell.get("technology")}
                       for cell in rat_cells}
                 for rat, rat_cells in self.node_info.get("cells").items()}
        self.scf.load_scf(self.scf_file)
        for lte_cell in self.node_info["cells"].get("lte", []):
            for cell, cell_details in cells["lte"].items():
                if lte_cell["id"]["configuration"] == cell:
                    try:
                        cell_details["IoT Mode"] = self.scf.get_value_from_scf(dist_name=cell, p_name="nbIoTMode")
                    except KeyError:
                        pass
                    try:
                        if lte_cell.get("technology") and "iot" in lte_cell["technology"].lower() and \
                                lte_cell["narrowbandIotMode"].lower() != "standalone":
                            cell_details["IoT Cell"] = True
                            cell_details["Linked Host Cell"] = self.get_linked_iot_cell(cells, cell, cell_details)
                        else:
                            cell_details["IoT Cell"] = False
                            cell_details["Linked IoT Cell"] = self.get_linked_iot_cell(cells, cell, cell_details)
                    except KeyError:
                        pass
                    try:
                        cell_details["DSS Cell"] = self._is_dss_cell_available(cell)
                    except KeyError:
                        pass
        for nr_cell in self.node_info["cells"].get("nr", []):
            for cell, cell_details in cells["nr"].items():
                if nr_cell["id"]["configuration"] == cell:
                    try:
                        cell_details["IoT Mode"] = self.scf.get_value_from_scf(dist_name=cell, p_name="nbIoTMode")
                        if cell_details["IoT Mode"].lower() == "guardband-nr":
                            cell_details["Linked IoT Cell"] = self.get_linked_iot_cell(cells, cell, cell_details)
                    except KeyError:
                        pass
                    try:
                        cell_details["DSS Cell"] = self._is_dss_cell_available(cell)
                    except KeyError:
                        pass
        return cells

    def get_duplex_mode(self):
        cell_technologies = {cell["technology"] for rat in self.cells_per_rat.values() for cell in rat.values()
                             if cell["technology"]}
        duplex_modes = list({"FDD" if "FDD" in technology.upper() else "TDD" for technology in cell_technologies})
        return duplex_modes[0] if len(duplex_modes) == 1 else "FDD+TDD"

    def _get_cell_by_id(self, host_cell_id, rat, cells=None):
        if not cells:
            cells = self.cells_per_rat
        if cells.get(rat):
            for cell in cells[rat].keys():
                if cell.split("-")[-1] == str(host_cell_id):
                    return cell

    def get_host_cell_by_id(self, linked_cell_id: str, rat: str, cells=None):
        if not cells:
            cells = self.cells_per_rat
        if cells.get(rat):
            for cell in cells[rat].keys():
                lcrid = self.scf.get_value_from_scf(dist_name=cell, p_name="lcrId")
                if linked_cell_id == str(lcrid):
                    return cell

    def get_linked_iot_cell(self, cells: dict, cell: str, cell_details: dict):
        iot_mode = cell_details["IoT Mode"].lower()
        technology = cell_details["technology"].lower()
        rat = "lte"
        if iot_mode == "guardband-nr" and technology == "nb-iot-fdd":
            cell_id = cell.split("-")[-1].lower()
            cell = f"{cell}/NBIOT_FDD-{cell_id}"
            nbiot_name = "nbIotLinkedNrCellLcrId"
            rat = "nr"
        elif iot_mode == "guardband-nr":
            nbiot_name = "nbIotLinkedLteCellLcrId"
        else:
            nbiot_name = "nbIotLinkedCellId"

        host_cell_id = self.scf.get_value_from_scf(dist_name=cell, p_name=nbiot_name)
        if cell_details["IoT Mode"].lower() in self.iot_modes:
            return self.get_host_cell_by_id(host_cell_id, rat, cells)
        return self._get_cell_by_id(host_cell_id, "lte", cells)

    def _is_dss_cell_available(self, cell: str):
        dss_cell = self.scf.get_value_from_scf(dist_name=cell, p_name="lteNrDssMode")
        if str(dss_cell) == 'none':
            return False
        return True
